(* [comment removed for export] *)
Ltac eqb_lit b c := first [ rewrite (proj2 (Z.eqb_neq b c)) by lia | rewrite (proj2 (Z.eqb_eq b c)) by lia | idtac ].
Ltac eqb_lits c := eqb_lit 43 c; eqb_lit 32 c; eqb_lit 10 c; eqb_lit 9 c; eqb_lit 0 c.

(* [comment removed for export] *)
Definition strchrnul_loop : Z := strchr_entry + 0x100.   (* [comment removed for export] *)
Ltac tail_loop :=
  let lp := eval cbv in strchrnul_loop in
  lazymatch goal with
  | |- evt _ _ (MS _ _ (Z_to_bv 64 ?p) _ _ _ _) =>
      tryif constr_eq p lp
      then (zstep; zstep; zstep; first [ ifT | ifF; zstep; let K := fresh "K" in (if_cases K; zify_cond K) ]; tail_loop)
      else idtac
  | |- _ => idtac
  end.

